// Simple follower parsing without external dependencies
const html = $input.first().json.data;

// Extract follower names using simple regex patterns
const followers = [];

// Look for LinkedIn profile links and names
const profileLinkRegex = /href="\/in\/([^"\?]+)[^"]*"/g;
const nameRegex = /<span[^>]*class="[^"]*(?:actor-name|name|t-16|t-black|t-bold)[^"]*"[^>]*>([^<]+)<\/span>/g;

let profileMatch;
const profileIds = [];
while ((profileMatch = profileLinkRegex.exec(html)) !== null) {
  profileIds.push(profileMatch[1]);
}

let nameMatch;
const names = [];
while ((nameMatch = nameRegex.exec(html)) !== null) {
  const name = nameMatch[1].trim();
  if (name && name.length > 1 && !name.includes('LinkedIn')) {
    names.push(name);
  }
}

// Match names with profile IDs (simple approach)
for (let i = 0; i < Math.min(profileIds.length, names.length); i++) {
  if (profileIds[i] && names[i]) {
    followers.push({
      name: names[i],
      profileId: profileIds[i],
      profileUrl: `https://linkedin.com/in/${profileIds[i]}`,
      scrapedAt: new Date().toISOString()
    });
  }
}

// Remove duplicates
const uniqueFollowers = followers.filter((follower, index, self) => 
  index === self.findIndex(f => f.profileId === follower.profileId)
);

console.log(`Found ${uniqueFollowers.length} unique followers`);

return uniqueFollowers.map(follower => ({ json: follower }));

// Check if follower is new
const currentFollower = $('parse-followers').item.json;
const existingFollowers = $input.first().json;

// Extract profile IDs from existing followers sheet
const existingProfileIds = existingFollowers.map(row => row[0]).filter(id => id && id.length > 0);

// Check if current follower is new
const isNewFollower = !existingProfileIds.includes(currentFollower.profileId);

if (isNewFollower) {
  return {
    json: {
      ...currentFollower,
      isNew: true
    }
  };
} else {
  // Return empty to stop workflow for this follower
  return null;
}

// Create personalized welcome message
const followerData = $input.first().json;
const fullName = followerData.name;
const firstName = fullName.split(' ')[0];

// Create personalized message
const personalizedMessage = `Hi ${firstName}! 👋

Thank you for following Creative Technology Collective! We're thrilled to have you join our community of innovators, creators, and tech enthusiasts.

🚀 Here's what you can expect:
• Cutting-edge insights on emerging technologies
• Exclusive access to our community resources
• Networking opportunities with fellow creatives
• Early access to our workshops and events

Feel free to reach out if you have any questions or ideas you'd like to share. We're always excited to connect with passionate individuals like yourself!

Welcome aboard! 🎉

Best regards,
The CTC Team

P.S. Check out our latest resources at creativetechnologists.nl`;

return {
  json: {
    profileId: followerData.profileId,
    profileUrl: followerData.profileUrl,
    fullName: fullName,
    firstName: firstName,
    message: personalizedMessage,
    timestamp: new Date().toISOString(),
    date: new Date().toLocaleDateString(),
    time: new Date().toLocaleTimeString()
  }
};

